class Solution {
public:
    string filterCharacters(string s, int k) {
        int cnt[26] = {0};
        for (char ch : s) cnt[ch - 'a']++;
        string res;
        for (char ch : s) if (cnt[ch - 'a'] < k) res += ch;
        return res;
    }
};

