class Solution {
    public String filterCharacters(String s, int k) {
        int[] cnt = new int[26];
        for (char ch : s.toCharArray()) cnt[ch - 'a']++;
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) if (cnt[ch - 'a'] < k) sb.append(ch);
        return sb.toString();
    }
}

